function D({registerIndicator:w,nulls:F}){w({id:"oa-pvd",name:"Price Volume Divergence (PVD)",category:"Volume",placement:"pane",inputs:[{key:"pricePeriod",type:"number",label:"Price Period",default:14,min:1,max:100,step:1},{key:"volumePeriod",type:"number",label:"Volume Period",default:14,min:1,max:100,step:1},{key:"divergenceThreshold",type:"number",label:"Divergence Threshold",default:50,min:0,max:1e5,step:1,tooltip:"Carried over from the source script, which declares it but does not use it in the plotted line."},{key:"smoothing",type:"number",label:"Smoothing Period",default:3,min:1,max:20,step:1}],plots:[{key:"pvd",type:"line",title:"PVD",style:{color:"#ffeb3b",lineWidth:2}}],calc(c,s){const v=Math.min(100,Math.max(1,Math.floor(Number(s.pricePeriod)||14))),f=Math.min(100,Math.max(1,Math.floor(Number(s.volumePeriod)||14))),N=Math.min(20,Math.max(1,Math.floor(Number(s.smoothing)||3))),t=c.length,u=new Array(t),d=new Array(t);for(let e=0;e<t;e++){const n=c[e].close;u[e]=Number.isFinite(n)?n:0;const r=c[e].volume;d[e]=Math.max(Number.isFinite(r)?r:0,1)}const y=new Array(t).fill(NaN),M=new Array(N).fill(NaN);let o=0,h=0,i=0;for(let e=0;e<t;e++){const n=e<v?Math.max(e,1):v,r=e<f?Math.max(e,1):f,P=e-n,x=e-r,a=P>=0?u[P]:NaN,l=x>=0?d[x]:NaN,p=Number.isFinite(a)&&a>0?(u[e]-a)/a*100:0,b=Number.isFinite(l)&&l>0?(d[e]-l)/l*100:0,V=p>0?1:p<0?-1:0,k=b>0?1:b<0?-1:0,A=Math.abs(p)+Math.abs(b),m=V*-k*A,g=M[o];Number.isFinite(g)&&(h-=g,i-=1),Number.isFinite(m)&&(h+=m,i+=1),M[o]=m,o=(o+1)%N,y[e]=i>0?h/i:m}return{pvd:F(y)}}})}export{D as default};
